import { CustomTypography } from "../materials/Typography";

import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemText from '@mui/material/ListItemText';
import DialogTitle from '@mui/material/DialogTitle';
import Dialog from '@mui/material/Dialog';
import PersonIcon from '@mui/icons-material/Person';
import AddIcon from '@mui/icons-material/Add';
import FolderIcon from '@mui/icons-material/Folder';
import { blue } from '@mui/material/colors';
import IconButton from '@mui/material/IconButton';
import DeleteIcon from '@mui/icons-material/Delete';
import { Avatar } from "@mantine/core/lib/components/Avatar/Avatar";

import SwitchAccessShortcutAdd from "@mui/icons-material/SwitchAccessShortcutAdd";
import YoutubeIcon from '@mui/icons-material/YouTube';
import Box from '@mui/material/Box';

export default function Contact() {

  return (
    <>
      <List dense={false}>
        <ListItem
            secondaryAction={
                <IconButton 
                    edge="end" 
                    aria-label="delete" 
                    component="a" 
                    href="https://www.youtube.com/@BatchedSupport" 
                    target="_blank" 
                    rel="noopener noreferrer"
                >
                    <SwitchAccessShortcutAdd />
                </IconButton>
            }
        >
            <ListItemAvatar>
                <YoutubeIcon />
            </ListItemAvatar>
            <ListItemText
                primary="YouTube" 
                secondary={true ? 'Batched Support Youtube Channel' : null}
            />
        </ListItem>
        <ListItem
            secondaryAction={
                <IconButton 
                    edge="end" 
                    aria-label="delete" 
                    component="a" 
                    href="https://youtu.be/7hvmRqilgsg" 
                    target="_blank" 
                    rel="noopener noreferrer"
                >
                    <SwitchAccessShortcutAdd />
                </IconButton>
            }
        >
            <ListItemAvatar>
                <YoutubeIcon />
            </ListItemAvatar>
            <ListItemText
                primary="YouTube" 
                secondary={true ? 'Batched Support Image Transfer Instructions' : null}
            />
            <Box>
                <iframe
                    src="https://www.youtube.com/embed/7hvmRqilgsg"
                    title="YouTube video player"
                    style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    }}
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                ></iframe>
            </Box>
        </ListItem>
    </List>
    </>
  )
}
